#[test]
fn execute_step_dry_run_shows_hooks() {
    let temp = TempDir::new().unwrap();
    let mut step = make_step("echo main");
    step.before = vec!["echo setup".to_string()];
    step.after = vec!["echo cleanup".to_string()];

    let ctx = InterpolationContext::new();
    let options = ExecutionOptions {
        dry_run: true,
        ..Default::default()
    };

    let result =
        execute_step(&step, temp.path(), &ctx, &HashMap::new(), &options, None).unwrap();

    assert!(result.success);
    let output = result.output.unwrap();
    assert!(output.contains("Would run: echo main"), "got: {}", output);
    assert!(
        output.contains("echo setup"),
        "should show before hook, got: {}",
        output
    );
    assert!(
        output.contains("echo cleanup"),
        "should show after hook, got: {}",
        output
    );
}

