            .map(|(k, v)| format!("{}={}", k, v))
            .collect();
        env_pairs.sort();
        lines.push(format!("  Env: {}", env_pairs.join(", ")));
    }

    return Ok(StepResult::success(
        &step.name,
        Duration::ZERO,
        None,
        Some(lines.join("\n")),
    ));
}

