    fn make_gap_checker() -> (EnvironmentProbe, RequirementRegistry) {
        let probe = EnvironmentProbe::run_with_env(|_| Err(std::env::VarError::NotPresent));
        let registry = RequirementRegistry::new();
        (probe, registry)
    }

